sys_script_include.script:
var ControlBaseUtils = Class.create();
ControlBaseUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    controlBase: function() {

        var city = this.getParameter("sysparm_city");
        var stateId = this.getParameter("sysparm_state");

        var grCityState = new GlideRecord("x_1593183_bases_base");
        grCityState.addQuery("city", city);
        grCityState.addQuery("state", stateId);
        grCityState.query();

        // Se encontrar qualquer base com o mesmo nome ou cidade+estado, retorna "true"
        if (grCityState.next()) {
            return "true"; // Base com o mesmo nome ou a mesma cidade+estado já existe
        } else {
            return "false"; // Nenhuma base com o mesmo nome ou cidade+estado foi encontrada
        }
    },

    type: 'ControlBaseUtils'
});
